ATTACH ':memory:' AS aux; CREATE TABLE aux.t1(x, y); CREATE TEMP TABLE t1(x, y); DROP TABLE t1; CREATE TABLE main.result(temp_count, main_count, aux_count); INSERT INTO main.result SELECT (SELECT count(*) FROM temp.sqlite_master WHERE type='table' AND name='t1'), (SELECT count(*) FROM main.sqlite_master WHERE type='table' AND name='t1'), (SELECT count(*) FROM aux.sqlite_master WHERE type='table' AND name='t1');